/**
 * Exact boluo1 pineapple house from CustomSRP FBX (authored UVs + oil maps).
 * Mesh generated by tools/boluo1_extract/obj_to_mesh.py from boluo1.fbx.
 */
import { boluo1Raw } from './data/boluo1.gen'
import type { MeshData } from './mesh'

/** Local-space pineapple house. Placement applies Unity MapItem TRS. */
export function pineappleHouse(_ox = 0, _oy = 0, _oz = 0, _scale = 1): MeshData {
  const { interleaved, indices } = boluo1Raw()
  // Optional uniform scale around origin (MapItem scale is applied in placed.ts).
  if (_scale !== 1 || _ox !== 0 || _oy !== 0 || _oz !== 0) {
    for (let i = 0; i < interleaved.length; i += 12) {
      interleaved[i] = interleaved[i] * _scale + _ox
      interleaved[i + 1] = interleaved[i + 1] * _scale + _oy
      interleaved[i + 2] = interleaved[i + 2] * _scale + _oz
    }
  }
  return {
    interleaved,
    indices,
    receiveShadow: true,
    doubleSided: true,
  }
}
